proc contractEventIndex*(name: string): int =
  ## Index into the tables above, -1 for a custom event. A `case` over string
  ## literals: no allocation, no table to share between threads.
  case name
  of evInit: 0
  of evRender: 1
  of evOpen: 2
  of evClose: 3
  of evKeyDown: 4
  of evKeyUp: 5
  of evTextInput: 6
  of evPointerMove: 7
  of evPointerDown: 8
  of evPointerUp: 9
  of evPointerCancel: 10
  of evMouseMove: 11
  of evMouseDown: 12
  of evMouseUp: 13
  of evTap: 14
  of evDoubleTap: 15
  of evLongPress: 16
  of evSwipe: 17
  of evWheel: 18
  of evTurnOn: 19
  of evTurnOff: 20
  of evButton: 21
  of evSetSceneState: 22
  of evSetCurrentScene: 23
  of evMetrics: 24
  of evReload: 25
  of evRestart: 26
  of evReboot: 27
  of evUploadScenes: 28
  else: -1

iterator eventAliases*(name: string): string =
  ## The old names a listener may know `name` by; the dispatcher delivers each
  ## one too, with that alias's own (smaller) payload.
  case name
  of evPointerMove:
    yield evMouseMove
  of evPointerDown:
    yield evMouseDown
  of evPointerUp:
    yield evMouseUp
  else: discard

iterator eventPayloadKeys*(name: string): string =
  ## The contract's payload fields of `name`, in order (nothing for a custom event).
  case name
  of evOpen:
    yield "sceneId"
  of evKeyDown:
    yield "code"
    yield "key"
    yield "repeat"
    yield "shift"
    yield "ctrl"
    yield "alt"
    yield "meta"
    yield "linuxCode"
  of evKeyUp:
