proc eventListenDefault*(name, field: string): string =
  ## What a listener of `name` with no filter on `field` hears: only events where
  ## the field equals this (`button` without an `action` filter hears presses).
  ## Empty: no such rule.
  case name
  of evButton:
    case field
    of "action": "press"
    else: ""
  else: ""

proc buttonRoleForLabel*(upperLabel: string): string =
  ## The default role of a GPIO button that has none configured, by its label
  ## (upper-cased by the caller); empty when the label says nothing.
  case upperLabel
  of "A": "primary"
  of "B": "next"
  of "C": "prev"
  of "D": "back"
  of "BOOT": "primary"
  of "KEY1": "next"
  of "KEY2": "prev"
  of "KEY3": "next"
  of "BUTTON": "primary"
  of "POWER": "primary"
  of "OK": "primary"
  of "ENTER": "primary"
  of "SELECT": "primary"
  of "HOME": "menu"
  of "MENU": "menu"
  of "EXIT": "back"
  of "BACK": "back"
  of "NEXT": "next"
  of "RIGHT": "next"
  of "PREV": "prev"
  of "LEFT": "prev"
  of "UP": "up"
  of "DOWN": "down"
  of "REFRESH": "refresh"
  else: ""
